import { execFile } from 'node:child_process'
import { promisify } from 'node:util'
import { existsSync } from 'node:fs'
import fsp from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { pathToFileURL } from 'node:url'
import { createTestDatabase, type TestDatabase } from '@opensaas/stack-core/testing'
import type { AccessControlledDB, OpenSaasConfig, StackContext } from '@opensaas/stack-core'

/**
 * A temp project generated by the real `opensaas` CLI over the toolchain
 * `examples/starter-auth` has installed, its database stood up by the core test
 * harness, and its generated context imported into this process — the shape
 * every live auth guard in this directory shares (ADR-0002, ADR-0057).
 *
 * The database is the harness's: in-process PGlite, or a fresh database on the
 * server `DATABASE_URL` names. The generated context finds it through the
 * same lookup the app would — the state file under the project's bundle on
 * the PGlite path, the variable on the escape — so it binds the way `opensaas
 * dev` binds it (ADR-0063). The lookup reads the state file from the process's
 * working directory, which is why this module changes it for the import and
 * restores it on close.
 *
 * Known limits:
 * - One project at a time per process: the generated bundle caches its client
 *   on `globalThis`, and the working directory is process-wide. `close()`
 *   clears both, so projects are used in sequence, never concurrently.
 */

const run = promisify(execFile)
const here = path.dirname(new URL(import.meta.url).pathname)
export const repoRoot = path.resolve(here, '../../..')

const opensaasCli = path.join(repoRoot, 'packages/cli/dist/index.js')
const coreDist = path.join(repoRoot, 'packages/core/dist')
const authDist = path.join(repoRoot, 'packages/auth/dist')
const toolchainNodeModules = path.join(repoRoot, 'examples/starter-auth/node_modules')

/** Whether the built packages and the borrowed toolchain are all on disk. */
export function toolchainPresent(): boolean {
  return (
    existsSync(opensaasCli) &&
    existsSync(coreDist) &&
    existsSync(authDist) &&
    existsSync(path.join(toolchainNodeModules, '.bin', 'opensaas')) &&
    existsSync(path.join(toolchainNodeModules, '@prisma', 'orm-postgres')) &&
    existsSync(path.join(toolchainNodeModules, 'better-auth', 'dist', 'test-utils'))
  )
}

export interface GeneratedProject {
  readonly dir: string
  readonly config: OpenSaasConfig
  readonly database: TestDatabase
  /** The project's own generated context, at the anonymous session. */
  readonly context: StackContext<AccessControlledDB>
  /** Resolve a module the borrowed toolchain installed, by path under `node_modules`. */
  toolchainModule(relativePath: string): Promise<unknown>
  close(): Promise<void>
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

function isOpenSaasConfig(value: unknown): value is OpenSaasConfig {
  return isRecord(value) && isRecord(value.lists) && isRecord(value.db)
}

function isStackContext(value: unknown): value is StackContext<AccessControlledDB> {
  return (
    isRecord(value) &&
    isRecord(value.db) &&
    typeof value.sudo === 'function' &&
    typeof value.transaction === 'function' &&
    'unsafe' in value
  )
}

function isThenable(value: unknown): value is PromiseLike<unknown> {
  return isRecord(value) && typeof value.then === 'function'
}

async function importDefault(file: string): Promise<unknown> {
  const module: unknown = await import(/* @vite-ignore */ pathToFileURL(file).href)
  const value = isRecord(module) ? module.default : undefined
  return isThenable(value) ? await value : value
}

async function importRawContext(file: string): Promise<unknown> {
  const module: unknown = await import(/* @vite-ignore */ pathToFileURL(file).href)
  return isRecord(module) ? await module.rawOpensaasContext : undefined
}

const ESCAPE_VARIABLES = ['DATABASE_URL', 'DIRECT_DATABASE_URL'] as const

/**
 * Write the config, generate the project, stand up its database and import its
 * context. `configSource` is the project's whole `opensaas.config.ts`.
 */
export async function generateProject(
  name: string,
  configSource: string,
  env: Record<string, string>,
): Promise<GeneratedProject> {
  const tmpRoot = await fsp.mkdtemp(path.join(os.tmpdir(), `opensaas-${name}-`))
  const dir = path.join(tmpRoot, 'project')
  await fsp.mkdir(dir, { recursive: true })
  await fsp.writeFile(path.join(dir, 'opensaas.config.ts'), configSource)
  await fsp.writeFile(
    path.join(dir, 'package.json'),
    JSON.stringify({ name: `${name}-project`, version: '0.0.0', private: true, type: 'module' }),
  )
  await fsp.symlink(toolchainNodeModules, path.join(dir, 'node_modules'))

  const subprocessEnv: Record<string, string | undefined> = { ...process.env, ...env }
  for (const variable of ESCAPE_VARIABLES) delete subprocessEnv[variable]
  await run(path.join(dir, 'node_modules', '.bin', 'opensaas'), ['generate'], {
    cwd: dir,
    env: subprocessEnv,
  })

  const config = await importDefault(path.join(dir, 'opensaas.config.ts'))
  if (!isOpenSaasConfig(config)) throw new Error(`${dir}/opensaas.config.ts exported no config`)

  const database = await createTestDatabase(config)

  const previousCwd = process.cwd()
  const previousEnv = new Map(ESCAPE_VARIABLES.map((v) => [v, process.env[v]] as const))
  for (const variable of ESCAPE_VARIABLES) delete process.env[variable]
  for (const [key, value] of Object.entries(env)) process.env[key] = value
  if (database.provenance === 'escape') {
    process.env.DATABASE_URL = database.url
  } else {
    await fsp.mkdir(path.join(dir, '.opensaas'), { recursive: true })
    await fsp.writeFile(
      path.join(dir, '.opensaas', 'dev-db.json'),
      JSON.stringify({ url: database.url, pid: process.pid }),
    )
  }
  process.chdir(dir)

  const context = await importRawContext(path.join(dir, '.opensaas', 'context.ts'))
  if (!isStackContext(context)) throw new Error(`${dir}/.opensaas/context.ts exported no context`)

  return {
    dir,
    config,
    database,
    context,
    toolchainModule: (relativePath) =>
      import(/* @vite-ignore */ pathToFileURL(path.join(dir, 'node_modules', relativePath)).href),
    close: async () => {
      process.chdir(previousCwd)
      for (const [variable, value] of previousEnv) {
        if (value === undefined) delete process.env[variable]
        else process.env[variable] = value
      }
      Reflect.deleteProperty(globalThis, 'opensaasClient')
      await database.close()
      await fsp.unlink(path.join(dir, 'node_modules'))
      await fsp.rm(tmpRoot, { recursive: true, force: true })
    },
  }
}
